from pathlib import Path
p=Path('proyeccion/paso2021_ciego')
data=(p/'visual_datos.json').read_text(encoding='utf8')
html=r'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PASO 2021 · aguja y proyección</title><style>
:root{color-scheme:light}*{box-sizing:border-box}body{font:15px/1.5 system-ui,sans-serif;color:#202020;background:white;max-width:1100px;margin:auto;padding:24px}h1{font-size:27px;margin:0}h2{font-size:18px;margin:24px 0 8px}.mu{color:#666;font-size:13px}header{border-bottom:1px solid #ddd;padding-bottom:16px}.controls{display:flex;gap:18px;align-items:center;flex-wrap:wrap;margin:18px 0}select{font:inherit;padding:8px 12px;border:1px solid #bbb;border-radius:4px;background:#fff;max-width:100%}label{cursor:pointer}.grid{display:grid;grid-template-columns:minmax(0,2fr) minmax(250px,1fr);gap:28px}.gauge{width:100%;display:block;max-height:470px}#map{max-height:430px;width:100%}.stats{display:flex;justify-content:space-between;text-align:center;gap:12px}.stats strong{display:block;font-size:31px}.stats small{font-size:12px;color:#666}.band{text-align:center;margin:12px 0}.notice{background:#f5f5f5;border-left:3px solid #bbb;padding:12px 15px;font-size:13px}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;margin:12px 0 24px;font-size:14px}th,td{padding:7px 9px;border-bottom:1px solid #e5e5e5;text-align:right;white-space:nowrap}td:first-child,th:first-child{text-align:left}.sw{display:inline-block;width:10px;height:10px;margin-right:7px}a{color:#17677e}footer{font-size:12px;color:#666;border-top:1px solid #ddd;padding-top:16px;margin-top:28px}.hide-real .actual{display:none}.legend{display:flex;flex-wrap:wrap;gap:12px;font-size:12px}.map-note{font-size:12px;color:#666}@media(max-width:700px){body{padding:15px}.grid{grid-template-columns:1fr}.stats strong{font-size:25px}h1{font-size:23px}#map{max-height:360px}}@media print{.controls{display:none}body{max-width:none}.grid{grid-template-columns:2fr 1fr}}
</style></head><body><header><p class="mu">RECONSTRUCCIÓN RETROSPECTIVA · DIPUTADOS NACIONALES · 12 SEPTIEMBRE 2021</p><h1>La aguja de las PASO 2021</h1><p class="mu">30 mesas · antecedentes 2019 + 2017 · primera colección de cada diseño, elegida antes de evaluar su acierto.</p></header><div class="controls"><label>Selección <select id="scheme" aria-label="Diseño de selección de mesas"></select></label><label><input type="checkbox" id="showreal" checked> Comparar con el resultado</label><button onclick="window.print()" style="font:inherit;padding:7px 12px;background:white;border:1px solid #bbb;border-radius:4px">Imprimir</button></div><div class="grid"><section><svg class="gauge" id="gauge" viewBox="0 0 700 365" role="img" aria-label="Aguja del margen Juntos por el Cambio menos Frente de Todos"></svg><div class="stats"><div style="color:#009ce4"><b>Frente de Todos</b><strong id="fp"></strong><small>primero en las remuestras</small></div><div><small>MARGEN ESTIMADO</small><strong id="margin"></strong></div><div style="color:#b48600"><b>Juntos por el Cambio</b><strong id="jp"></strong><small>primero en las remuestras</small></div></div><p class="band" id="band"></p><p class="mu" id="support" style="text-align:center"></p><p class="actual mu" id="actualmargin" style="text-align:center"></p></section><section><h2>Fuerza más votada por distrito</h2><svg id="map" role="img" aria-label="Mapa de la proyección por distrito"></svg><div class="legend" id="legend"></div><p class="map-note">Colores de la proyección. Pasá el puntero sobre cada provincia para ver los porcentajes.</p></section></div><h2>Proyección nacional</h2><div class="scroll"><table><thead><tr><th>Fuerza</th><th>Proyección</th><th>Banda nominal 95 %</th><th class="actual">Resultado</th><th class="actual">Error</th></tr></thead><tbody id="national"></tbody></table></div><div class="notice">Las frecuencias de las remuestras son condicionales al modelo. La prueba encontró subcobertura con selección sesgada y para fuerzas emergentes fuera de sus zonas fuertes. Estos porcentajes no son una certeza electoral calibrada.</div><h2>Comparar los siete diseños</h2><p class="mu">Cada fila usa su primera colección de 30 mesas. Son muestras distintas, no la evolución cronológica de una misma noche.</p><div class="scroll"><table><thead><tr><th>Diseño</th><th>Margen proyectado</th><th>Banda nominal 95 %</th><th class="actual">Error del margen</th></tr></thead><tbody id="comparison"></tbody></table></div><h2>Por distrito</h2><div class="scroll"><table><thead><tr><th>Distrito</th><th>JXC</th><th>FDT</th><th>FIT</th><th>LIB</th><th>Otras</th></tr></thead><tbody id="district"></tbody></table></div><footer>Modelo temporal: λ=0,1 elegido con 2017; bandas ×1,5 calibradas con 2019. Predicciones de 30 mesas conservadas antes de abrir el total de PASO 2021. La arquitectura se desarrolló retrospectivamente con conocimiento de elecciones posteriores. Porcentajes sobre votos positivos del provisorio territorial disponible, agrupados en familias políticas; no son internas entre listas. Las PASO no asignan bancas.<p><a href="RESULTADOS.md">Informe de las 700 colecciones</a> · <a href="PROTOCOLO.md">Protocolo</a> · <a href="aguja_paso2021.png">Aguja PNG</a></p></footer><script>
const D=__DATA__;
const $=id=>document.getElementById(id), fmt=v=>Number(v).toFixed(1).replace('.',','), signed=v=>(v>=0?'+':'−')+fmt(Math.abs(v));
const NS='http://www.w3.org/2000/svg';function el(t,a={},text){const n=document.createElementNS(NS,t);Object.entries(a).forEach(([k,v])=>n.setAttribute(k,v));if(text!==undefined)n.textContent=text;return n}
function pos(v,r){const a=(180-180*Math.max(-30,Math.min(30,v))/30)/2*Math.PI/180;return [350+r*Math.cos(a),295-r*Math.sin(a)]}
function sector(l,h,outer,inner){let p=pos(l,outer),q=pos(h,outer),u=pos(h,inner),v=pos(l,inner);return `M${p} A${outer},${outer} 0 0 1 ${q} L${u} A${inner},${inner} 0 0 0 ${v} Z`}
function gauge(r){let svg=$('gauge');svg.replaceChildren();for(const [l,h,c] of [[-30,-15,'#009ce4'],[-15,-5,'#55b9e6'],[-5,-1,'#a8dff5'],[-1,1,'#ddd'],[1,5,'#f4e3ac'],[5,15,'#e8c65c'],[15,30,'#d6a211']])svg.append(el('path',{d:sector(l,h,250,150),fill:c,stroke:'white','stroke-width':3}));svg.append(el('text',{x:350,y:22,'text-anchor':'middle',fill:'#777','font-size':12},'EMPATE'));for(const v of [-30,-20,-10,10,20,30]){let p=pos(v,273);svg.append(el('text',{x:p[0],y:p[1]+5,'text-anchor':'middle',fill:'#777','font-size':13},'+'+Math.abs(v)))}let [lo,hi]=r.margen_banda;svg.append(el('path',{d:sector(lo,hi,143,0),fill:'#555',opacity:.17}));const p=pos(r.margen,245),ang=Math.atan2(295-p[1],p[0]-350),nx=7*Math.sin(ang),ny=7*Math.cos(ang);svg.append(el('polygon',{points:`${p} ${350+nx},${295+ny} ${350-nx},${295-ny}`,fill:'#171717'}));svg.append(el('circle',{cx:350,cy:295,r:12,fill:'#171717'}));svg.append(el('text',{x:95,y:345,'text-anchor':'middle',fill:'#009ce4','font-size':13},'VENTAJA FDT'));svg.append(el('text',{x:605,y:345,'text-anchor':'middle',fill:'#a67c00','font-size':13},'VENTAJA JXC'))}
function draw(){let r=D.samples[$('scheme').value];gauge(r);$('fp').textContent=fmt(100*r.prob_primero[1])+' %';$('jp').textContent=fmt(100*r.prob_primero[0])+' %';$('margin').textContent=(r.margen>=0?'JXC +':'FDT +')+fmt(Math.abs(r.margen));$('band').textContent='Banda nominal 95 % del margen JXC−FDT: '+signed(r.margen_banda[0])+' a '+signed(r.margen_banda[1]);$('support').textContent='30 mesas · '+r.circuitos+' circuitos · colección 1 de 100';$('actualmargin').textContent='Resultado del universo evaluado: JXC +'+fmt(D.real.margen_JXC_FDT)+' · error de esta colección: '+signed(r.margen-D.real.margen_JXC_FDT);
$('national').innerHTML=D.forces.map((f,i)=>`<tr><td><span class="sw" style="background:${D.colors[f]}"></span>${D.names[f]}</td><td><b>${fmt(r.punto[i])} %</b></td><td>${fmt(r.lo[i])}–${fmt(r.hi[i])}</td><td class="actual">${fmt(D.real.nacional[f])} %</td><td class="actual">${signed(r.punto[i]-D.real.nacional[f])}</td></tr>`).join('');$('district').innerHTML=r.distritos.map((d,i)=>`<tr><td>${D.districts[d]}</td>${r.porcentaje_distrito[i].map(v=>`<td>${fmt(v)}</td>`).join('')}</tr>`).join('');let map=$('map');map.replaceChildren();map.setAttribute('viewBox',D.view.join(' '));for(const [d,path] of Object.entries(D.paths)){let i=r.distritos.indexOf(d);if(i<0)continue;let vals=r.porcentaje_distrito[i],winner=D.forces[vals.indexOf(Math.max(...vals))];let n=el('path',{d:path,fill:D.colors[winner],stroke:'white','stroke-width':2});n.append(el('title',{},D.districts[d]+' · '+D.forces.map((f,j)=>f+' '+fmt(vals[j])+' %').join(' / ')));map.append(n)}document.body.classList.toggle('hide-real',!$('showreal').checked)}
$('scheme').innerHTML=Object.entries(D.schemes).map(([k,v])=>`<option value="${k}">${v}</option>`).join('');$('scheme').value='twitter';$('scheme').onchange=draw;$('showreal').onchange=draw;$('legend').innerHTML=D.forces.map(f=>`<span><i class="sw" style="background:${D.colors[f]}"></i>${f}</span>`).join('');$('comparison').innerHTML=Object.entries(D.schemes).map(([k,label])=>{let r=D.samples[k];return `<tr><td>${label}</td><td>${signed(r.margen)}</td><td>${signed(r.margen_banda[0])} a ${signed(r.margen_banda[1])}</td><td class="actual">${signed(r.margen-D.real.margen_JXC_FDT)}</td></tr>`}).join('');draw();
</script></body></html>'''
(p/'aguja_paso2021.html').write_text(html.replace('__DATA__',data),encoding='utf8')
print('HTML autocontenido generado')
